package com.cpf.core.common.runtimecontrol.applier;import com.cpf.core.api.runtimecontrol.*;import com.cpf.core.common.attachment.CpfAttachmentRuntimePolicy;
public final class CpfDownloadPolicyRuntimeApplier implements CpfRuntimeChangeApplier{private final CpfAttachmentRuntimePolicy p;public CpfDownloadPolicyRuntimeApplier(CpfAttachmentRuntimePolicy p){this.p=p;}public String changeType(){return "DOWNLOAD_POLICY";}public boolean supportsIdempotentReplay(){return true;}public boolean snapshotCapable(){return true;}public CpfRuntimeApplyResult apply(CpfRuntimeDelivery d){try{p.replaceDownload(d.desiredVersion(),bool(d.payload().get("permissionRequired"),true),bool(d.payload().get("approvalRequired"),false),num(d.payload().get("linkExpirySeconds"),3600),bool(d.payload().get("watermarkRequired"),false));return CpfRuntimeApplyResult.success(d.payloadHash());}catch(RuntimeException e){return CpfRuntimeApplyResult.failure("DOWNLOAD_POLICY_INVALID","Download policy payload 오류");}}private long num(Object v,long f){return v instanceof Number n?n.longValue():v==null?f:Long.parseLong(String.valueOf(v));}private boolean bool(Object v,boolean f){return v instanceof Boolean b?b:v==null?f:Boolean.parseBoolean(String.valueOf(v));}}
